import {Img, staticFile} from 'remotion';

/**
 * STEAM FOCUS lockup (owner's choice): the official Steam logo, unchanged, followed by
 * FOCUS. The SVG is generated by brand/make_steam_lockup.py into public/brand/steam_focus/
 * (Valve artwork is fetched locally and not committed). Being vector, it rasterizes
 * natively at the composition's resolution (4K in RedlineFull4K).
 */
export const LOCKUP_RATIO = 481.6 / 93.4; // width / height of the lockup viewBox

export const Lockup: React.FC<{height: number; variant?: 'dark' | 'light' | 'mono_white' | 'mono_dark'; style?: React.CSSProperties}> = ({
  height,
  variant = 'dark',
  style,
}) => <Img src={staticFile(`brand/steam_focus/steam_focus_${variant}.svg`)} style={{height, width: height * LOCKUP_RATIO, display: 'block', ...style}} />;
